@page "/recipes"
@page "/recipes/{Category}"

<PageTitle>Recipes - @(Category ?? "All Categories")</PageTitle>

<h1>@(Category is not null ? FormatCategory(Category) : "All Recipes")</h1>

@if (Category is null)
{
    <ul>
        <li><a href="recipes/appetizers">Appetizers</a></li>
        <li><a href="recipes/main-courses">Main Courses</a></li>
        <li><a href="recipes/desserts">Desserts</a></li>
    </ul>
}
else
{
    <div class="row">
        @foreach (var recipe in GetRecipesForCategory(Category))
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Summary</p>
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string? Category { get; set; }

    private string FormatCategory(string category) => category.Replace("-", " ").ToUpperInvariant() switch
    {
        var s when s.Length > 0 => char.ToUpper(category[0]) + category[1..].Replace("-", " "),
        _ => category
    };

    private List<RecipeSummary> GetRecipesForCategory(string category) => category switch
    {
        "appetizers" => new()
        {
            new(1, "Bruschetta", "Classic Italian tomato and basil bruschetta."),
            new(2, "Stuffed Mushrooms", "Cream cheese and herb stuffed mushrooms."),
        },
        "main-courses" => new()
        {
            new(3, "Spaghetti Carbonara", "Creamy Roman pasta with pancetta and egg."),
            new(4, "Grilled Salmon", "Lemon herb grilled salmon with vegetables."),
        },
        "desserts" => new()
        {
            new(5, "Tiramisu", "Coffee-flavored Italian layered dessert."),
            new(6, "Chocolate Lava Cake", "Rich molten chocolate cake with a gooey center."),
        },
        _ => new()
    };

    private record RecipeSummary(int Id, string Title, string Summary);
}

@page "/recipe/{Id:int}"

<PageTitle>@recipe.Title - RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="recipes">Recipes</a></li>
        <li class="breadcrumb-item"><a href="recipes/@recipe.Category">@recipe.CategoryDisplay</a></li>
        <li class="breadcrumb-item active">@recipe.Title</li>
    </ol>
</nav>

<h1>@recipe.Title</h1>

<StarRating RecipeId="Id" @rendermode="InteractiveServer" />

<h2>Ingredients</h2>
<ul>
    @foreach (var ingredient in recipe.Ingredients)
    {
        <li>@ingredient</li>
    }
</ul>

<h2>Steps</h2>
<ol>
    @foreach (var step in recipe.Steps)
    {
        <li>@step</li>
    }
</ol>

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe recipe = default!;

    protected override void OnParametersSet()
    {
        recipe = GetRecipe(Id);
    }

    private Recipe GetRecipe(int id) => id switch
    {
        1 => new("Bruschetta", "appetizers", "Appetizers",
            new[] { "1 baguette, sliced", "4 tomatoes, diced", "Fresh basil", "2 cloves garlic", "Olive oil", "Salt and pepper" },
            new[] { "Toast baguette slices until golden.", "Mix diced tomatoes with chopped basil, minced garlic, and olive oil.", "Season with salt and pepper.", "Spoon tomato mixture onto toasted bread.", "Serve immediately." }),
        2 => new("Stuffed Mushrooms", "appetizers", "Appetizers",
            new[] { "12 large mushrooms", "8 oz cream cheese", "Fresh herbs (thyme, parsley)", "2 cloves garlic", "Breadcrumbs", "Parmesan cheese" },
            new[] { "Preheat oven to 375°F.", "Remove stems from mushrooms and hollow caps.", "Mix cream cheese, herbs, garlic, and breadcrumbs.", "Fill mushroom caps with mixture.", "Top with parmesan and bake 20 minutes." }),
        3 => new("Spaghetti Carbonara", "main-courses", "Main Courses",
            new[] { "400g spaghetti", "200g pancetta", "4 egg yolks", "100g Pecorino Romano", "Black pepper" },
            new[] { "Cook spaghetti in salted boiling water until al dente.", "Fry pancetta until crispy.", "Whisk egg yolks with grated cheese and pepper.", "Drain pasta, reserving some water.", "Toss hot pasta with pancetta, then stir in egg mixture off heat.", "Add pasta water if needed for creaminess." }),
        4 => new("Grilled Salmon", "main-courses", "Main Courses",
            new[] { "4 salmon fillets", "2 lemons", "Fresh dill", "Olive oil", "Asparagus", "Salt and pepper" },
            new[] { "Marinate salmon with lemon juice, dill, and olive oil for 30 minutes.", "Preheat grill to medium-high.", "Season asparagus with oil, salt, and pepper.", "Grill salmon 4-5 minutes per side.", "Grill asparagus alongside until tender.", "Serve with lemon wedges." }),
        5 => new("Tiramisu", "desserts", "Desserts",
            new[] { "6 egg yolks", "500g mascarpone", "300ml strong espresso", "Ladyfinger biscuits", "Cocoa powder", "Sugar" },
            new[] { "Whisk egg yolks with sugar until pale and thick.", "Fold in mascarpone until smooth.", "Dip ladyfingers briefly in cooled espresso.", "Layer dipped biscuits in a dish.", "Spread mascarpone mixture over biscuits.", "Repeat layers and refrigerate 4+ hours.", "Dust with cocoa powder before serving." }),
        6 => new("Chocolate Lava Cake", "desserts", "Desserts",
            new[] { "200g dark chocolate", "100g butter", "3 eggs", "100g sugar", "50g flour", "Butter for ramekins" },
            new[] { "Preheat oven to 425°F. Butter 4 ramekins.", "Melt chocolate and butter together.", "Whisk eggs and sugar until fluffy.", "Fold chocolate mixture into eggs, then fold in flour.", "Pour into ramekins.", "Bake 12-14 minutes until edges are set but center is soft.", "Invert onto plates and serve immediately." }),
        _ => new("Recipe Not Found", "appetizers", "Appetizers", Array.Empty<string>(), Array.Empty<string>())
    };

    private record Recipe(string Title, string Category, string CategoryDisplay, string[] Ingredients, string[] Steps);
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Thank you!</h4>
        <p>Your recipe "<strong>@Model.Title</strong>" has been submitted for review.</p>
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="Model.Title" />
            <ValidationMessage For="() => Model.Title" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="Model.Ingredients" />
            <ValidationMessage For="() => Model.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Model.Steps" />
            <ValidationMessage For="() => Model.Steps" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel Model { get; set; } = new();
    private bool submitted;

    private void HandleSubmit()
    {
        submitted = true;
    }

    private void Reset()
    {
        Model = new();
        submitted = false;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        [System.ComponentModel.DataAnnotations.StringLength(100)]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list at least one ingredient.")]
        public string Ingredients { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please describe the preparation steps.")]
        public string Steps { get; set; } = "";
    }
}

@rendermode InteractiveServer

<div class="star-rating my-3">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= currentRating ? "selected" : "")"
              @onclick="() => SetRating(star)"
              role="button"
              title="@star star(s)">
            @(star <= currentRating ? "★" : "☆")
        </span>
    }
    @if (currentRating > 0)
    {
        <span class="ms-2 text-muted">You rated this @currentRating/5</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int currentRating;

    private void SetRating(int rating)
    {
        currentRating = rating;
    }
}

.star-rating {
    font-size: 1.5rem;
}

.star {
    cursor: pointer;
    color: #ccc;
    transition: color 0.2s;
}

.star:hover,
.star.selected {
    color: #f5a623;
}

